import fs from "node:fs/promises";
import path from "node:path";
import { console } from "@ndn/util";
import { CertStore } from "./cert-store_node.js";
import { KeyStore } from "./key-store_node.js";
import { MemoryStoreProvider } from "./store-base_node.js";
class FileStoreProvider {
    filename;
    canSClone = false;
    ms = new MemoryStoreProvider();
    loaded = false;
    saveDebounce;
    constructor(filename) {
        this.filename = filename;
    }
    async load() {
        if (this.loaded) {
            return;
        }
        try {
            this.ms.record = JSON.parse(await fs.readFile(this.filename, "utf8"));
        }
        catch (err) {
            if (err.code === "ENOENT" || err.name === "SyntaxError") {
                this.ms.record = {};
            }
            else {
                throw err;
            }
        }
        this.loaded = true;
    }
    save() {
        if (this.saveDebounce) {
            this.saveDebounce.refresh();
        }
        else {
            this.saveDebounce = setTimeout(this.doSave, 200);
        }
    }
    doSave = async () => {
        this.saveDebounce = undefined;
        try {
            await fs.mkdir(path.dirname(this.filename), { recursive: true });
            await fs.writeFile(this.filename, JSON.stringify(this.ms.record));
        }
        catch (err) {
            console.error(`FileStoreProvider(${this.filename}) write error ${err}`);
        }
    };
    async list() {
        await this.load();
        return this.ms.list();
    }
    async get(key) {
        await this.load();
        return this.ms.get(key);
    }
    async insert(key, value) {
        await this.load();
        this.ms.insert(key, value);
        this.save();
    }
    async erase(key) {
        await this.load();
        this.ms.erase(key);
        this.save();
    }
}
export function openStores(locator, algoList) {
    return [
        new KeyStore(new FileStoreProvider(`${locator}/fdd08d47-ec4d-4112-a5ce-898338ab0399.json`), algoList),
        new CertStore(new FileStoreProvider(`${locator}/d29e6de4-d5dd-4222-b2e2-d06e4046e7f9.json`)),
    ];
}
